    source.connect(filter);
    filter.connect(volume);
    volume.connect(this.master);
    source.start(now);
    source.stop(now + duration + 0.02);
  }

  pop(hard = false) {
    if (!this.enabled || this.throttled('pop', 22)) return;
    const base = hard ? 170 : 330 + Math.random() * 160;
