const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

const wait = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await chromium.launch({ headless: true });
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  const errors = [];
  page.on('console', msg => { if (msg.type() === 'error') errors.push(`console: ${msg.text()}`); });
  page.on('pageerror', err => errors.push(`pageerror: ${err.message}`));
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'networkidle' });
  await wait(600);

  const shot = (name) => page.screenshot({ path: `/home/runner/work/PlayGround/PlayGround/screenshots/${name}.png` });
  const getState = () => page.evaluate(() => {
    const s = window.__bloonBlitz.state;
    return {
      phase: s.phase, paused: s.paused, speed: s.speed, lives: s.lives, cash: Math.floor(s.cash), round: s.round,
      freeplay: s.freeplay, towers: s.towers.map(t => ({type:t.type, level:t.level, target:t.targetMode, spent:t.spent})),
      bloons: s.bloons.length, queue: s.spawnQueue.length, autoTimer: +s.autoTimer.toFixed(1),
      pops: s.stats.pops, selected: s.selectedTower ? {type:s.selectedTower.type, level:s.selectedTower.level, target:s.selectedTower.targetMode} : null,
      selectedType: s.selectedType, resultShown: s.resultShown,
      dialog: {help: document.querySelector('#helpDialog').open, result: document.querySelector('#resultDialog').open, pauseHidden: document.querySelector('#pauseScreen').hidden},
      inspector: !document.querySelector('#towerPanel').hidden,
      shop: !document.querySelector('#shopPanel').hidden,
      tip: document.querySelector('#boardTip').textContent,
      start: document.querySelector('#startBtn .start-copy strong').textContent,
      waveState: document.querySelector('#waveState').textContent,
    };
  });
  const clickWorld = async (wx, wy) => {
    const pt = await page.evaluate(([x,y]) => {
      const c = document.querySelector('#gameCanvas');
      const r = c.getBoundingClientRect();
      const scale = Math.min(r.width/1200, r.height/760);
      const ox = (r.width - 1200*scale)/2, oy = (r.height - 760*scale)/2;
      return {x:r.left+ox+x*scale, y:r.top+oy+y*scale};
    }, [wx,wy]);
    await page.mouse.click(pt.x, pt.y);
  };
  const log = async (label) => console.log(label, JSON.stringify(await getState()));

  console.log('--- initial ---'); await log('initial');

  // Build one dart monkey with real click.
  await page.click('.shop-card[data-type="dart"]');
  await wait(100);
  await clickWorld(250, 300);
  await wait(250);
  console.log('--- built ---'); await log('built');
  await shot('test-built');

  // Inspector, targeting, upgrade, sell.
  await page.click('#cycleTarget');
  await wait(100);
  await log('targeted');
  await page.click('[data-upgrade="0"]');
  await wait(150);
  await log('upgraded');
  await shot('test-upgraded');
  await page.click('#sellTower');
  await wait(150);
  await log('sold');

  // Build a small defense via debug for wave 1.
  await page.evaluate(() => {
    const b = window.__bloonBlitz;
    b.addCash(5000);
    for (const [type, x, y] of [['dart',250,300],['bomb',490,250],['ice',520,430],['boomerang',760,300],['glue',610,590]]) {
      b.selectBuild(type); b.placeTower(x,y);
    }
    b.state.selectedTower = null;
    b.selectBuild('dart'); b.selectBuild('dart'); // cancel
  });
  await wait(150);
  await log('defense');

  // Start wave and run at 3x.
  await page.click('#startBtn');
  await page.click('#speedBtn'); await page.click('#speedBtn');
  await wait(300);
  console.log('--- wave1 active ---'); await log('wave1');
  await shot('test-wave-active');

  let result = null;
  for (let i = 0; i < 300; i++) {
    const s = await getState();
    if (s.phase !== 'active') { result = s; break; }
    await wait(100);
  }
  console.log('--- wave1 done ---'); console.log(JSON.stringify(result));
  await shot('test-between');

  // Auto-start next wave (shorten countdown).
  await page.evaluate(() => { window.__bloonBlitz.state.autoTimer = 0.2; });
  await wait(700);
  console.log('--- auto-start wave2 ---'); await log('wave2');

  // Pause/resume.
  await page.click('#pauseBtn');
  await wait(100);
  await log('paused');
  await page.click('#resumeBtn');
  await wait(100);
  await log('resumed');

  // Help pauses and resumes.
  await page.click('#helpBtn');
  await wait(100);
  await log('help-open');
  await page.click('#helpClose');
  await wait(100);
  await log('help-closed');

  // Force victory result.
  await page.evaluate(() => {
    const s = window.__bloonBlitz.state;
    s.phase = 'active'; s.round = 49; s.freeplay = false; s.bloons = []; s.spawnQueue = []; s.autoTimer = 0;
    window.__bloonBlitz.completeWave();
  });
  await wait(1100);
  await log('victory-dialog');
  await shot('test-victory');
  const victoryVisible = await page.locator('#resultContinue').isVisible();
  console.log('victory continue visible', victoryVisible);
  await page.click('#resultContinue');
  await wait(150);
  await log('freeplay-between');
  await page.click('#startBtn');
  await wait(300);
  await log('freeplay-wave51');
  await shot('test-freeplay');

  // Defeat flow.
  await page.evaluate(() => {
    const b = window.__bloonBlitz;
    b.resetGame();
    const s = b.state;
    s.phase = 'active';
    s.lives = 1;
    s.bloons = [];
    s.spawnQueue = [];
    b.createBloon('red', 99999);
  });
  await wait(1600);
  await log('defeat-dialog');
  await shot('test-defeat');
  const defeatContinueHidden = await page.locator('#resultContinue').isHidden();
  console.log('defeat continue hidden', defeatContinueHidden);
  await page.click('#resultRestart');
  await wait(250);
  await log('after-restart');

  // Persistence / settings checks.
  console.log('localStorage', await page.evaluate(() => localStorage.getItem('bloon-blitz-settings')));
  console.log('ERRORS', JSON.stringify(errors));
  await browser.close();
})();

