const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const wait = (ms) => new Promise(r => setTimeout(r, ms));
const shotDir = '/home/runner/work/PlayGround/PlayGround/screenshots';

(async () => {
  const browser = await chromium.launch({ headless: true });
  const errors = [];
  async function newPage(viewport, mobile = false) {
    const ctx = await browser.newContext({ viewport, deviceScaleFactor: mobile ? 2 : 1, isMobile: mobile, hasTouch: mobile });
    const page = await ctx.newPage();
    page.on('console', msg => { if (msg.type() === 'error') errors.push(`${viewport.width}x${viewport.height}: ${msg.text()}`); });
    page.on('pageerror', err => errors.push(`${viewport.width}x${viewport.height}: PAGEERROR ${err.message}`));
    await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
    await wait(500);
    return { ctx, page };
  }
  const state = (page) => page.evaluate(() => {
    const s = window.__bloonBlitz.state;
    return {phase:s.phase,round:s.round,cash:Math.floor(s.cash),freeplay:s.freeplay,lives:s.lives,paused:s.paused,
      towers:s.towers.length, selected:!!s.selectedTower, resultShown:s.resultShown,
      resultOpen: document.querySelector('#resultDialog').open, helpOpen: document.querySelector('#helpDialog').open,
      continueVisible: !document.querySelector('#resultContinue').hidden,
      resultTitle: document.querySelector('#resultTitle').textContent,
      tip: document.querySelector('#boardTip').textContent,
      overflow: [document.body.scrollWidth, document.body.scrollHeight]};
  });
  const worldTap = async (page, wx, wy) => {
    const pt = await page.evaluate(([x,y]) => {
      const c = document.querySelector('#gameCanvas');
      const r = c.getBoundingClientRect();
      const scale = Math.min(r.width/1200, r.height/760);
      const ox = (r.width - 1200*scale)/2, oy = (r.height - 760*scale)/2;
      return {x:r.left+ox+x*scale, y:r.top+oy+y*scale};
    }, [wx,wy]);
    await page.touchscreen.tap(pt.x, pt.y);
  };

  // --- Desktop results / freeplay / defeat ---
  const { ctx: dctx, page: d } = await newPage({width:1440,height:900});
  await d.evaluate(() => {
    const s = window.__bloonBlitz.state;
    s.phase = 'active'; s.round = 50; s.freeplay = false; s.bloons = []; s.spawnQueue = []; s.autoTimer = 0;
    window.__bloonBlitz.completeWave();
  });
  await wait(1100);
  console.log('victory', JSON.stringify(await state(d)));
  await d.screenshot({ path: `${shotDir}/test-victory.png` });
  await d.click('#resultContinue');
  await wait(200);
  console.log('freeplay between', JSON.stringify(await state(d)));
  await d.click('#startBtn');
  await wait(400);
  console.log('freeplay wave', JSON.stringify(await state(d)));
  await d.screenshot({ path: `${shotDir}/test-freeplay.png` });
  await d.evaluate(() => window.__bloonBlitz.resetGame());
  await wait(200);
  await d.evaluate(() => {
    const b = window.__bloonBlitz;
    const s = b.state;
    s.phase = 'active'; s.lives = 1; s.bloons = []; s.spawnQueue = [];
    b.createBloon('red', 99999);
  });
  await wait(1700);
  console.log('defeat', JSON.stringify(await state(d)));
  await d.screenshot({ path: `${shotDir}/test-defeat.png` });
  await d.click('#resultRestart');
  await wait(250);
  console.log('restarted', JSON.stringify(await state(d)));
  await dctx.close();

  // --- Mobile portrait interaction ---
  const { ctx: mctx, page: m } = await newPage({width:390,height:844}, true);
  console.log('mobile initial', JSON.stringify(await state(m)));
  console.log('mobile help visible', await m.locator('#helpBtn').isVisible(), 'overflow', await m.evaluate(() => [document.body.scrollWidth, document.body.scrollHeight]));
  await m.screenshot({ path: `${shotDir}/mobile-4.png` });
  await m.tap('.shop-card[data-type="dart"]');
  await wait(150);
  await worldTap(m, 250, 300);
  await wait(300);
  console.log('mobile built', JSON.stringify(await state(m)));
  await m.screenshot({ path: `${shotDir}/mobile-inspector.png` });
  await m.tap('[data-upgrade="0"]');
  await wait(200);
  console.log('mobile upgraded', JSON.stringify(await state(m)));
  await m.tap('#cycleTarget');
  await wait(150);
  console.log('mobile target', JSON.stringify(await m.evaluate(() => window.__bloonBlitz.state.selectedTower.targetMode)));
  await m.screenshot({ path: `${shotDir}/mobile-inspector-upgraded.png` });
  await m.tap('#closeInspector');
  await wait(200);
  console.log('mobile shop restored', JSON.stringify(await state(m)));
  await m.tap('#helpBtn');
  await wait(250);
  console.log('mobile help open', JSON.stringify(await state(m)));
  await m.screenshot({ path: `${shotDir}/mobile-help.png` });
  await m.tap('#helpPlay');
  await wait(150);
  console.log('mobile help closed', JSON.stringify(await state(m)));

  // Start a wave on mobile and tap pause.
  await m.tap('#startBtn');
  await wait(500);
  await m.tap('#pauseBtn');
  await wait(200);
  console.log('mobile paused', JSON.stringify(await state(m)));
  await m.screenshot({ path: `${shotDir}/mobile-paused.png` });
  await m.tap('#resumeBtn');
  await wait(150);
  console.log('mobile resumed', JSON.stringify(await state(m)));
  await mctx.close();

  // --- Landscape phone ---
  const { ctx: lctx, page: l } = await newPage({width:844,height:390}, true);
  console.log('landscape initial', JSON.stringify(await state(l)));
  console.log('landscape help visible', await l.locator('#helpBtn').isVisible(), 'overflow', await l.evaluate(() => [document.body.scrollWidth, document.body.scrollHeight]));
  await l.screenshot({ path: `${shotDir}/landscape-2.png` });
  await l.tap('#helpBtn');
  await wait(200);
  await l.screenshot({ path: `${shotDir}/landscape-help.png` });
  await l.tap('#helpPlay');
  await lctx.close();

  console.log('ERRORS', JSON.stringify(errors));
  await browser.close();
})();

