/* ---------- Tower inspector ---------- */

.tower-panel {
  min-height: 0;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  padding: 14px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(200,245,62,.24) transparent;
  animation: panel-in .2s ease;
}

@keyframes panel-in {
  from { opacity: 0; transform: translateY(5px); }
  to { opacity: 1; transform: translateY(0); }
}

.tower-head {
  display: flex;
  align-items: center;
  gap: 10px;
}

.tower-portrait {
  width: 62px;
  height: 62px;
  border-radius: 15px;
  flex: 0 0 auto;
  background:
    radial-gradient(circle at 50% 34%, rgba(255,255,255,.16), transparent 55%),
    color-mix(in srgb, var(--tint) 20%, #0b2a1e);
  border: 1px solid color-mix(in srgb, var(--tint) 32%, transparent);
  overflow: hidden;
}

.tower-portrait canvas { width: 100%; height: 100%; display: block; }

.tower-head-copy {
  flex: 1;
  min-width: 0;
}

.tower-head-copy h2 {
  margin: 0;
  font-family: var(--font-display);
  font-size: 19px;
  line-height: 1.1;
  letter-spacing: -.35px;
  color: #fbf8e7;
}

.tower-head-copy p {
  margin: 4px 0 0;
  color: #8db19a;
  font-size: 10px;
  line-height: 1.35;
}

.tower-stars {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  margin-top: 5px;
  color: rgba(255, 209, 92, .28);
  font-size: 10px;
}

.tower-stars .is-lit { color: var(--gold); filter: drop-shadow(0 0 5px rgba(255,209,92,.35)); }

.close-inspector {
  width: 30px;
  height: 30px;
  border-radius: 9px;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.08);
  color: #a5c1ad;
  font-size: 16px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
}

.close-inspector:hover { background: rgba(255,255,255,.12); }

.tower-stat-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 5px;
  margin: 11px 0;
}

.tower-stat {
  padding: 7px 7px 6px;
  border-radius: 9px;
  background: rgba(0, 15, 9, .35);
  border: 1px solid rgba(255,255,255,.055);
}

.tower-stat span {
  display: block;
  font-size: 7.5px;
  color: #6d927d;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: .8px;
}

.tower-stat strong {
  display: block;
  margin-top: 3px;
  font-family: var(--font-display);
  font-size: 13px;
  color: #e8f3d9;
}

.upgrade-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
}

.upgrade-heading span:first-child {
  color: #719782;
  font-size: 8.5px;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 1.2px;
}

.upgrade-heading span:last-child {
  color: #608471;
  font-size: 8.5px;
  font-weight: 800;
}

.upgrade-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.upgrade-row {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: 49px;
  padding: 6px 7px;
  border-radius: 10px;
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.06);
  text-align: left;
  transition: .15s ease;
  overflow: hidden;
}

.upgrade-row:hover:not(:disabled) {
  background: rgba(255,255,255,.065);
  border-color: rgba(200,245,62,.22);
}

.upgrade-row.is-next {
  border-color: rgba(200,245,62,.2);
  background: linear-gradient(90deg, rgba(200,245,62,.075), rgba(255,255,255,.025));
}

.upgrade-row.is-locked { opacity: .46; filter: saturate(.35); }
.upgrade-row.is-maxed { border-color: rgba(255,209,92,.16); background: rgba(255,209,92,.045); }
.upgrade-row:disabled { cursor: default; }

.upgrade-tier {
  width: 22px;
  height: 22px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 7px;
  font: 900 9px var(--font-display);
  color: #8cb39b;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.08);
}

.upgrade-row.is-next .upgrade-tier { color: #1b330c; background: var(--lime); border-color: transparent; }
.upgrade-row.is-maxed .upgrade-tier { color: #3b2a05; background: var(--gold); border-color: transparent; }

.upgrade-copy {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.upgrade-copy strong {
  font-size: 10.5px;
  color: #e8f4db;
  line-height: 1.15;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.upgrade-copy span {
  font-size: 8.5px;
  color: #799d87;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.upgrade-cost {
  display: flex;
  align-items: center;
  gap: 2px;
  padding-left: 3px;
  font-size: 10px;
  font-weight: 900;
  color: var(--gold);
  flex: 0 0 auto;
  font-variant-numeric: tabular-nums;
}

.upgrade-cost svg { font-size: 10px; }
.upgrade-cost.is-short { color: #ff8d7e; }
.upgrade-cost.is-done { color: rgba(255,209,92,.65); font-size: 8px; text-transform: uppercase; letter-spacing: .7px; }

.tower-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin-top: 9px;
}

.tower-action {
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border-radius: 9px;
  border: 1px solid rgba(255,255,255,.09);
  background: rgba(255,255,255,.05);
  color: #c9dec8;
  font-size: 10px;
  font-weight: 900;
  transition: .15s ease;
}

.tower-action:hover { background: rgba(255,255,255,.1); }
.tower-action svg { font-size: 12px; }
.tower-action.sell { color: #ffb4a4; }
.tower-action.sell:hover { background: rgba(255,110,88,.12); border-color: rgba(255,130,100,.22); }

.tower-tip {
  margin: 9px 2px 0;
  color: #658a75;
  font-size: 9px;
  line-height: 1.45;
}

.sidebar-foot {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 5px 11px;
  padding: 0 5px;
  color: #5f816e;
  font-size: 8.5px;
  font-weight: 700;
}

