const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const wait = (ms) => new Promise(r => setTimeout(r, ms));
(async () => {
  const browser = await chromium.launch();
  const errors = [];
  async function open(w,h,mobile) {
    const ctx = await browser.newContext({viewport:{width:w,height:h},deviceScaleFactor:mobile?2:1,isMobile:mobile,hasTouch:mobile});
    const page = await ctx.newPage();
    page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
    page.on('pageerror',e=>errors.push(e.message));
    await page.goto('http://localhost:3002',{waitUntil:'networkidle'});
    await wait(400);
    return {ctx,page};
  }
  let {ctx,page} = await open(390,844,true);
  const mb = await page.evaluate(()=>{
    const r = s=>{const el=document.querySelector(s),b=el.getBoundingClientRect();return {x:+b.x.toFixed(1),right:+b.right.toFixed(1),w:+b.width.toFixed(1)}};
    return {body:[document.body.scrollWidth,document.body.scrollHeight], topbar:r('.topbar'), brand:r('.brand'), stats:r('.stat-strip'), actions:r('.top-actions'), help:r('#helpBtn'), auto:r('.auto-chip'), start:r('.start-button'), combat:r('.icon-button')};
  });
  console.log('mobile390',JSON.stringify(mb));
  await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/mobile-5.png'});
  await page.tap('#helpBtn'); await wait(200);
  await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/mobile-help-2.png'});
  console.log('mobile help scroll', await page.evaluate(()=>{const d=document.querySelector('#helpDialog'); return {h:d.getBoundingClientRect().height, sh:d.scrollHeight, ch:d.clientHeight, overflow:getComputedStyle(d).overflowY}}));
  await page.tap('#helpPlay'); await ctx.close();

  ({ctx,page} = await open(844,390,true));
  console.log('landscape controls', await page.evaluate(()=>{
    const r=s=>{const b=document.querySelector(s).getBoundingClientRect();return {x:+b.x.toFixed(1),right:+b.right.toFixed(1),y:+b.y.toFixed(1),bottom:+b.bottom.toFixed(1)}};
    return {body:[document.body.scrollWidth,document.body.scrollHeight],help:r('#helpBtn'),actions:r('.top-actions')};
  }));
  await page.tap('#helpBtn'); await wait(200);
  console.log('landscape help', await page.evaluate(()=>{const d=document.querySelector('#helpDialog');return {rect:d.getBoundingClientRect().toJSON(),sh:d.scrollHeight,ch:d.clientHeight,overflow:getComputedStyle(d).overflowY};}));
  await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/landscape-help-2.png'});
  await page.tap('#helpPlay'); await wait(150);
  await page.evaluate(()=>{const b=window.__bloonBlitz,s=b.state;s.phase='active';s.round=50;s.bloons=[];s.spawnQueue=[];b.completeWave();});
  await wait(1100);
  await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/landscape-victory.png'});
  console.log('landscape result', await page.evaluate(()=>{const d=document.querySelector('#resultDialog');return {rect:d.getBoundingClientRect().toJSON(),sh:d.scrollHeight,ch:d.clientHeight,overflow:getComputedStyle(d).overflowY};}));
  await ctx.close();
  console.log('ERRORS',errors);
  await browser.close();
})();

