import { TOWERS, TOWER_ORDER, WAVES, getWave, TOTAL_ROUNDS, BLOONS, TARGET_MODES, BLOON_ORDER } from './js/data.js';
for (const key of TOWER_ORDER) {
  const d = TOWERS[key];
  const t = { range:d.range, damage:d.damage, pierce:d.pierce, shots:d.shots, cooldown:d.cooldown, splash:d.splash, slow:d.slow, slowTime:d.slowTime, dot:d.dot, freeze:d.freeze, income:d.income };
  try { for (const u of d.upgrades) u.apply(t); } catch (e) { console.log('UPGRADE ERROR', key, e.message); }
  console.log(key, d.name, 'upgrades', d.upgrades.length, 'final', JSON.stringify(t));
}
for (let r=1;r<=55;r++) {
  const w = getWave(r);
  for (const g of w.groups) {
    if (!BLOONS[g.type]) console.log('BAD BLOON', r, g.type);
    if (!(g.count>0 && g.gap>0)) console.log('BAD GROUP', r, g);
  }
}
console.log('waves', WAVES.length, 'rounds', TOTAL_ROUNDS, 'orders', TOWER_ORDER.length, BLOON_ORDER.length, 'targets', TARGET_MODES.map(t=>t.key).join(','));
console.log('duplicate tower ids?', new Set(TOWER_ORDER).size === TOWER_ORDER.length);
JS

