const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const wait = (ms) => new Promise(r => setTimeout(r, ms));
(async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({viewport:{width:1440,height:900}});
  const page = await ctx.newPage();
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push(`PAGEERROR ${e.message}`));
  await page.goto('http://localhost:3002', {waitUntil:'networkidle'});
  await wait(300);
  const types = await page.evaluate(() => window.__bloonBlitz.TOWERS && Object.keys(window.__bloonBlitz.TOWERS));
  for (const type of types) {
    const placed = await page.evaluate((type) => {
      const b = window.__bloonBlitz;
      b.resetGame();
      b.addCash(50000);
      b.selectBuild(type);
      return b.placeTower(250, 300);
    }, type);
    if (!placed) { console.log('PLACEMENT FAIL', type); continue; }
    await wait(100);
    for (let i = 0; i < 3; i++) {
      const row = page.locator(`[data-upgrade="${i}"]`);
      if (await row.count()) await row.click();
      await wait(80);
    }
    const data = await page.evaluate(() => {
      const s = window.__bloonBlitz.state;
      const t = s.towers[0];
      return {type:t.type, level:t.level, stats:{dmg:t.damage, range:t.range, shots:t.shots, cooldown:t.cooldown, splash:t.splash, slow:t.slow, dot:t.dot, freeze:t.freeze, income:t.income}, target:t.targetMode, targetDisabled: document.querySelector('#cycleTarget')?.disabled, tip: document.querySelector('#boardTip').textContent};
    });
    if (data.targetDisabled === false) {
      await page.click('#cycleTarget'); await wait(60);
      data.targetAfter = (await page.evaluate(() => window.__bloonBlitz.state.selectedTower?.targetMode));
    }
    await page.click('#sellTower'); await wait(80);
    data.afterSell = await page.evaluate(() => ({towers: window.__bloonBlitz.state.towers.length, tip: document.querySelector('#boardTip').textContent}));
    console.log(type, JSON.stringify(data));
  }
  console.log('ERRORS', JSON.stringify(errors));
  await browser.close();
})();

