 for (const [w,h] of sizes) {
  const ctx = await browser.newContext({viewport:{width:w,height:h},isMobile:true,hasTouch:true,deviceScaleFactor:1});
  const page = await ctx.newPage();
  await page.goto('http://localhost:3002',{waitUntil:'networkidle'});
  await wait(250);
  const r = await page.evaluate(() => {
    const b = s => { const e=document.querySelector(s); const r=e.getBoundingClientRect(); return {x:+r.x.toFixed(1),r:+r.right.toFixed(1),y:+r.y.toFixed(1),b:+r.bottom.toFixed(1),w:+r.width.toFixed(1),h:+r.height.toFixed(1)}; };
    const over = [...document.querySelectorAll('body *')].filter(e=>{const r=e.getBoundingClientRect(); return r.width>0 && (r.right>innerWidth+.5 || r.left<-.5);}).slice(0,10).map(e=>({c:e.className?.baseVal||e.className,t:e.innerText?.trim().slice(0,20),r:+e.getBoundingClientRect().right.toFixed(1)}));
    return {body:[document.body.scrollWidth,document.body.scrollHeight], topbar:b('.topbar'), brand:b('.brand'), stats:b('.stat-strip'), acts:b('.top-actions'), board:b('.board-card'), wave:b('.wave-panel'), shop:b('.shop-panel'), cta:b('.board-cta'), over};
  });
  console.log(`${w}x${h}`, JSON.stringify(r));
  if (w===375) await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/mobile-375.png'});
  if (w===320) await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/mobile-320.png'});
  await ctx.close();
 }
 await browser.close();
})();

