input.content:
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const wait = ms => new Promise(r=>setTimeout(r,ms));
(async()=>{
 const browser=await chromium.launch();
 const ctx=await browser.newContext({viewport:{width:1440,height:900}});
 const page=await ctx.newPage(); const errors=[];
 page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
 page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://localhost:3002',{waitUntil:'networkidle'});
 await page.evaluate(()=>localStorage.clear()); await page.reload({waitUntil:'networkidle'}); await wait(400);

 // Place tower via keyboard + canvas click to exercise keyboard path.
 await page.keyboard.press('1');
 await wait(100);
 const pt = await page.evaluate(()=>{const c=document.querySelector('#gameCanvas'),r=c.getBoundingClientRect(),s=Math.min(r.width/1200,r.height/760),ox=(r.width-1200*s)/2,oy=(r.height-760*s)/2;return{x:r.left+ox+250*s,y:r.top+oy+300*s};});
 await page.mouse.click(pt.x,pt.y); await wait(150);
 console.log('keyboard build', await page.evaluate(()=>({towers:window.__bloonBlitz.state.towers.length,cash:window.__bloonBlitz.state.cash, inspector:!document.querySelector('#towerPanel').hidden})));

 // Toggle sound / auto and verify persisted after reload.
 await page.click('#soundBtn'); await page.click('#autoBtn'); await wait(100);
 const beforeReload=await page.evaluate(()=>({settings:localStorage.getItem('bloon-blitz-settings'),snd:document.querySelector('#soundIcon').getAttribute('href'),auto:document.querySelector('#autoBtn').classList.contains('is-on')}));
 console.log('toggles',beforeReload);
 await page.reload({waitUntil:'networkidle'}); await wait(400);
 console.log('after reload',await page.evaluate(()=>({snd:document.querySelector('#soundIcon').getAttribute('href'),auto:document.querySelector('#autoBtn').classList.contains('is-on'),best:document.querySelector('#bestValue').textContent})));

 // Complete round 5 to persist a best wave, then reload.
 await page.evaluate(()=>{const b=window.__bloonBlitz,s=b.state;s.phase='active';s.round=5;s.bloons=[];s.spawnQueue=[];b.completeWave();});
 await wait(200);
 console.log('after round5',await page.evaluate(()=>({phase:window.__bloonBlitz.state.phase,best:document.querySelector('#bestValue').textContent,storage:localStorage.getItem('bloon-blitz-settings')})));
 await page.reload({waitUntil:'networkidle'}); await wait(400);
 console.log('persisted best',await page.evaluate(()=>({best:document.querySelector('#bestValue').textContent,phase:window.__bloonBlitz.state.phase})));

 // Victory -> freeplay headers.
 await page.evaluate(()=>{const b=window.__bloonBlitz,s=b.state;s.phase='active';s.round=50;s.freeplay=false;s.bloons=[];s.spawnQueue=[];b.completeWave();});
 await wait(1100);
 await page.click('#resultContinue'); await wait(200);
 console.log('freeplay header',await page.evaluate(()=>({round:document.querySelector('#roundValue').textContent,total:document.querySelector('#roundTotal').textContent,waveTotal:document.querySelector('#waveTotal').textContent,next:document.querySelector('#nextWaveValue').textContent,best:document.querySelector('#bestValue').textContent,phase:window.__bloonBlitz.state.phase,freeplay:window.__bloonBlitz.state.freeplay})));

 // Run 6 seconds to confirm auto-start disabled -> stays between.
 await page.click('#startBtn'); await wait(400);
 await page.click('#speedBtn'); await page.click('#speedBtn'); // 3x
 await wait(4500);
 console.log('wave51 running',await page.evaluate(()=>({phase:window.__bloonBlitz.state.phase,round:window.__bloonBlitz.state.round,bloons:window.__bloonBlitz.state.bloons.length,queue:window.__bloonBlitz.state.spawnQueue.length})));
 await page.evaluate(()=>window.__bloonBlitz.resetGame()); await wait(200);
 console.log('reset',await page.evaluate(()=>({phase:window.__bloonBlitz.state.phase,round:document.querySelector('#roundValue').textContent,total:document.querySelector('#roundTotal').textContent,waveTotal:document.querySelector('#waveTotal').textContent})));

 // Final desktop screenshot.
 await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/final-desktop.png'});
 console.log('ERRORS',JSON.stringify(errors));
 await browser.close();
})();

