  background: radial-gradient(circle at 34% 28%, rgba(255,255,255,.9), transparent 35%), var(--bloon-color);
  box-shadow: 0 0 7px color-mix(in srgb, var(--bloon-color) 60%, transparent);
  flex: none;
}

.sandbox-bloon.is-blimp .sandbox-bloon-dot { width: 18px; border-radius: 50% / 42%; }

.sandbox-actions {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
}

.sandbox-action {
  height: 27px;
  padding: 0 10px;
  border-radius: 8px;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.11);
  color: #c9e2bf;
  font-size: 8.5px;
  font-weight: 900;
  transition: background .14s ease;
}

.sandbox-action:hover { background: rgba(255,255,255,.12); }
.sandbox-action.is-exit { margin-left: auto; color: #ffd5c6; border-color: rgba(255,148,105,.24); background: rgba(255,116,80,.08); }

.map-modal { width: min(900px, calc(100vw - 28px)); }

.map-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 11px;
  margin-top: 19px;
}

.map-card {
  min-width: 0;
  padding: 0;
  overflow: hidden;
  text-align: left;
  border-radius: 16px;
  background: rgba(255,255,255,.035);
  border: 1px solid rgba(255,255,255,.09);
  color: var(--cream);
  cursor: pointer;
  transition: border-color .16s ease, background .16s ease, transform .16s ease, box-shadow .16s ease;
}

.map-card:hover { background: rgba(255,255,255,.065); border-color: rgba(200,245,62,.24); transform: translateY(-1px); }
.map-card.is-selected { border-color: rgba(200,245,62,.74); box-shadow: 0 0 0 2px rgba(200,245,62,.12), 0 14px 26px rgba(0,0,0,.2); background: rgba(200,245,62,.055); }
.map-card:focus-visible { outline: 2px solid rgba(200,245,62,.7); outline-offset: 2px; }

.map-preview-wrap { position: relative; display: block; height: 122px; overflow: hidden; background: #173927; }
.map-preview { display: block; width: 100%; height: 100%; }

.map-chip,
.map-track-count,
.map-current {
  position: absolute;
  display: inline-flex;
  align-items: center;
  height: 21px;
  padding: 0 8px;
  border-radius: 999px;
  font-size: 7.5px;
  font-weight: 900;
  letter-spacing: .8px;
  text-transform: uppercase;
  backdrop-filter: blur(7px);
}

.map-chip { top: 8px; left: 8px; color: #10240a; background: #c8f53e; }
.map-chip.is-beginner { background: #c8f53e; color: #1c3007; }
.map-chip.is-intermediate { background: #ffd15c; color: #392407; }
.map-chip.is-advanced { background: #7ad9ff; color: #062b39; }
.map-chip.is-expert { background: #ff805d; color: #3d1007; }
.map-track-count { top: 8px; right: 8px; background: rgba(4, 24, 16, .68); border: 1px solid rgba(255,255,255,.14); color: #edf8df; }
.map-current { right: 8px; bottom: 8px; background: rgba(200,245,62,.9); color: #182b08; }

.map-card-body { display: flex; flex-direction: column; gap: 3px; padding: 10px 12px 11px; }
.map-card-body > strong { font-family: var(--font-display); font-size: 15px; letter-spacing: -.2px; color: #fffbe9; }
.map-card-body > small { color: #8eae99; font-size: 9.5px; line-height: 1.4; min-height: 27px; }

.map-card-meta { display: flex; flex-wrap: wrap; gap: 4px 11px; margin-top: 2px; color: #b8d3bf; font-size: 8.5px; font-weight: 800; }
.map-card-meta span { display: inline-flex; align-items: center; gap: 4px; }
.map-card-meta svg { width: 10px; height: 10px; font-size: 10px; color: var(--gold); }

.map-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 13px;
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px solid rgba(255,255,255,.08);
}

.map-foot p { margin: 0; max-width: 480px; color: #789986; font-size: 9.5px; line-height: 1.45; }
.map-foot .primary-button { flex: none; min-width: 168px; }

.difficulty-pill.is-sandbox { color: #17300b; background: var(--lime); border-color: rgba(200,245,62,.4); }

'''
