 .sandbox-bloon{height:28px;font-size:8px;padding:0 8px 0 6px}
 .sandbox-action{height:26px;font-size:8px}
}
@media (max-width: 980px) and (max-height:520px) and (orientation:landscape) {
 .map-modal{...}
 .map-grid{grid-template-columns:repeat(2,1fr);gap:6px;margin-top:8px}
 .map-preview-wrap{height:62px}
 .map-card-body{padding:5px 7px 6px;gap:1px}
 .map-card-body>strong{font-size:11px}
 .map-card-body>small{display:none}
 .map-card-meta{font-size:7px}
 .map-foot{margin-top:7px;padding-top:7px}
 .map-foot p{font-size:7.5px}
 .map-foot .primary-button{height:30px;min-width:130px;font-size:9px}
 .sandbox-bar{left:8px;right:8px;bottom:8px;padding:6px 8px;gap:5px;border-radius:12px}
 .sandbox-head{display:none}
 .sandbox-bloon{height:26px;font-size:7.5px}
 .sandbox-action{height:24px;font-size:7.5px}
}
